const b=$('AIS Technolabs Blog Webhook').item.json.body||{};
const marketMap={'India':{code:2356,gl:'in'},'United States':{code:2840,gl:'us'},'United Kingdom':{code:2826,gl:'uk'},'UAE':{code:2784,gl:'ae'},'Canada':{code:2124,gl:'ca'},'Australia':{code:2036,gl:'au'},'Global':{code:2840,gl:'us'}};
const m=marketMap[b.target_market]||marketMap['United States'];
const wc=(b.word_count||'1200-1800').split('-');
const facts=(b.brand_facts||'')+(b.products_to_feature?('\n\nProducts to feature (use exact names as written):\n'+b.products_to_feature):'');
return [{ json:{
  request_id:b.request_id||('run-'+$execution.id),
  brand:b.brand||'AIS Technolabs',
  website:b.website||'https://www.aistechnolabs.com/',
  niche:b.niche||'iGaming & Casino Software (B2B)',
  primary_topic:b.primary_topic,
  location_code:m.code, gl:m.gl, hl:(b.language||'English')==='Hindi'?'hi':'en',
  brand_voice:b.brand_voice||'', brand_facts:facts,
  approved_claims:b.approved_claims||'', banned_terms:b.banned_terms||'',
  author_bio:b.author_bio||'', cta:b.cta||'', compliance:b.compliance_disclaimer||'',
  wc_min:parseInt(wc[0])||1200, wc_max:parseInt(wc[1])||1800,
  kw_count:parseInt(b.kw_count)||14, seed_keywords:b.seed_keywords||'',
  internal_links:b.internal_links||'', publish_target:b.publish_target||'Draft to webhook only',
  notify_email:b.notify_email||'' } }];

const cfg=$('Normalize Inputs (Webhook)').item.json;
const serper=$('Serper — Search & PAA').item.json;
const dfs=($('DataForSEO — Volume').item.json?.tasks?.[0]?.result)||[];
const vol={}; dfs.forEach(r=>{vol[(r.keyword||'').toLowerCase()]={v:r.search_volume||0,comp:r.competition_index||50};});
const pool=new Set();
(serper.relatedSearches||[]).forEach(r=>pool.add(r.query));
(serper.peopleAlsoAsk||[]).forEach(r=>pool.add(r.question));
(cfg.seed_keywords||'').split(',').map(s=>s.trim()).filter(Boolean).forEach(k=>pool.add(k));
let scored=[...pool].map(k=>{const mm=vol[k.toLowerCase()]||{v:0,comp:50}; return {kw:k,volume:mm.v,difficulty:mm.comp,score:mm.v/(mm.comp+10)};}).filter(x=>x.kw&&x.kw.length>3);
scored.sort((a,b)=>b.score-a.score);
const top=scored.slice(0,cfg.kw_count);
const primary=top.find(t=>t.volume>0)||top[0]||{kw:cfg.primary_topic};
const competitors=(serper.organic||[]).slice(0,3).map(o=>({title:o.title,link:o.link,snippet:o.snippet}));
return [{ json:{ primary_keyword:primary.kw, keywords:top.map(k=>k.kw), competitors } }];

const cfg=$('Normalize Inputs (Webhook)').item.json; const kb=$json;
return [{ json:{ brand:cfg.brand, website:cfg.website, niche:cfg.niche, brand_voice:cfg.brand_voice,
  brand_facts:cfg.brand_facts, approved_claims:cfg.approved_claims, banned_terms:cfg.banned_terms,
  author_bio:cfg.author_bio, cta:cfg.cta, compliance:cfg.compliance, internal_links:cfg.internal_links,
  wc_min:cfg.wc_min, wc_max:cfg.wc_max, primary_keyword:kb.primary_keyword, keywords:kb.keywords,
  competitors:kb.competitors, publish_target:cfg.publish_target, notify_email:cfg.notify_email } }];

const get=(name)=>{const j=$(name).item.json; return (j.choices?.[0]?.message?.content)??j.message?.content??j.content??'';};
const ctx=$('Assemble Context').item.json;
let body=get('Pass 5 · GEO Structuring');
body=body.replace(/^\s*```(?:html)?\s*/i,'').replace(/\s*```\s*$/,'');
const J=s=>{try{return JSON.parse(s.replace(/```json|```/g,'').trim());}catch(e){return null;}};
const meta=J(get('Pass 6 · Metadata'))||{}; const faq=J(get('Pass 4 · AEO FAQ'))||{};
// force-append the compliance disclaimer if the model dropped it
const disc=ctx.compliance||'';
if(disc && !body.includes(disc.slice(0,30))){ body += '\n<p class="disclaimer"><em>'+disc+'</em></p>'; }
const flags=[];
(ctx.banned_terms||'').split(',').map(s=>s.trim()).filter(Boolean).forEach(b=>{if(body.toLowerCase().includes(b.toLowerCase()))flags.push('banned:'+b);});
// iGaming-specific compliance scan: revenue/profit/ROI guarantees, gambling outcome claims
['guaranteed revenue','guaranteed profit','guaranteed ROI','guaranteed players','cure','cures','treats','permanent','miracle'].forEach(w=>{if(new RegExp('\\b'+w.replace(/\s+/g,'\\s+'),'i').test(body))flags.push('compliance:'+w);});
// Price verification — flag any $ / ₹ / Rs price not in brand_facts
const prices=body.match(/(₹|Rs\.?\s?|\$)[0-9,]+/g)||[];
prices.forEach(p=>{if(!(ctx.brand_facts||'').replace(/\s/g,'').includes(p.replace(/\s/g,'')))flags.push('unverified-price:'+p);});
if(!meta.article_schema)flags.push('schema-missing');
const status=flags.length?'NEEDS_FIX':'PENDING_REVIEW';
return [{ json:{ timestamp:new Date().toISOString(), brand:ctx.brand, primary_keyword:ctx.primary_keyword,
  keywords:(ctx.keywords||[]).join(', '), title:meta.meta_title||ctx.primary_keyword,
  meta_title:meta.meta_title||'', meta_description:meta.meta_description||'', slug:meta.slug||'',
  body_html:body, faq_json:JSON.stringify(faq.faq||faq), schema_json:JSON.stringify({article:meta.article_schema,faq:faq.faq_schema}),
  status, flags:flags.join('; '), publish_target:ctx.publish_target, notify_email:ctx.notify_email,
  request_id:$('Normalize Inputs (Webhook)').item.json.request_id||'' } }];
